import test from 'node:test';
import assert from 'node:assert/strict';
const mod=await import('../../docs/shared/ai-connection/operational-management.mjs').catch(e=>e.code==='ERR_MODULE_NOT_FOUND'?{}:Promise.reject(e));
const deferred=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve};};
const tensor=()=>({dtype:'float32',shape:[1,2],layout:'BC',meaning:'control-owned-value',data:new Float32Array([3,7]),arbitrary:{frames:[3,3,0],times:[.2,.2,0],mask:new Uint8Array([1,0])}});
function setup(behavior={}){const calls=[],instances=[];const services={controlTestOnly:true,createModule:async({moduleId,configuration})=>{const instance={moduleId,configuration,active:null,disposed:false,async execute(request){calls.push({moduleId,request});const gate=deferred();this.active={requestId:request.requestId};request.onProgress?.({phase:'started'});if(behavior.execute)return behavior.execute({instance:this,request,gate});const t=request.input?.tensor??tensor();this.active=null;return {status:'EXECUTION_COMPLETED',tensor:t,result:{tensor:t,nativeExtra:{mask:new Uint8Array([1,0])}},inputMetadata:{arbitrary:'retained'},terminal:{originalTerminal:true,resourceReleased:true,resultAccepted:true,reusable:true}};},query:async()=>({status:'SUPPORTED',reasons:[]}),inspect(){return {activeTarget:this.active,disposed:this.disposed};},async cancel(target){return behavior.cancel?behavior.cancel({instance:this,target}):{stopped:true,originalTerminal:true,resourceReleased:true,reusable:true};},async dispose(){this.disposed=true;}};instances.push(instance);return instance;}};return {services,calls,instances};}
const create=services=>{assert.equal(typeof mod.createOperationalManagement,'function');return mod.createOperationalManagement({services});};
test('explicit control seam, lazy owner configuration, full response and owned route references',async()=>{const f=setup(),host=create(f.services);assert.equal(f.instances.length,0);assert.equal(host.inspect().controlTestDouble,true);await host.configureModule('text',{marker:'one'});await host.configureModule('vae',{});const route=await host.executeRoute({steps:[{stepId:'later',moduleId:'vae',operation:'decode',input:{tensor:{$ref:'encoded',path:'result.tensor'}},outputRef:'decoded'},{stepId:'first',moduleId:'text',operation:'encode',input:{prompt:'ordinary'},outputRef:'encoded'}]});assert.deepEqual(f.calls.map(v=>v.moduleId),['text','vae']);assert.deepEqual(f.calls[1].request.input.tensor.data,new Float32Array([3,7]));assert.deepEqual(route.artifacts.encoded.response.result.nativeExtra.mask,new Uint8Array([1,0]));f.calls[1].request.input.tensor.data[0]=900;assert.equal(route.artifacts.encoded.tensor.data[0],3);assert.deepEqual(route.finalRefs,['decoded']);await host.dispose();});
test('cycle, absent and unsafe refs reject before owner dispatch; ordinary route needs no numeric refs',async()=>{const f=setup(),host=create(f.services);await host.configureModule('text',{});for(const steps of [[{stepId:'a',moduleId:'text',operation:'encode',input:{$ref:'b'},outputRef:'a'},{stepId:'b',moduleId:'text',operation:'encode',input:{$ref:'a'},outputRef:'b'}],[{stepId:'a',moduleId:'text',operation:'encode',input:{$ref:'missing'},outputRef:'a'}]])await assert.rejects(host.executeRoute({steps}),{code:'PIPELINE_INVALID'});assert.equal(f.calls.length,0);await host.execute({moduleId:'text',operation:'encode',input:{},outputRef:'ok'});await assert.rejects(host.execute({moduleId:'text',operation:'encode',input:{$ref:'ok',path:'__proto__.x'}}),{code:'INVALID_REFERENCE_PATH'});assert.equal(f.calls.length,1);await host.dispose();});
test('reconfiguration discards delayed old progress/result and disposes previous owner',async()=>{const entered=deferred(),finish=deferred(),f=setup({execute:async({request})=>{entered.resolve(request);await finish.promise;request.onProgress?.({phase:'late'});return {status:'EXECUTION_COMPLETED',tensor:tensor()};},cancel:async()=>{finish.resolve();return {stopped:true,originalTerminal:true,resourceReleased:true,reusable:true};}}),host=create(f.services),events=[];host.subscribe(e=>events.push(e));await host.configureModule('text',{manifest:'old'});const execution=host.execute({moduleId:'text',operation:'encode',input:{},outputRef:'old'});await entered.promise;const rejection=assert.rejects(execution);await host.configureModule('text',{manifest:'new'});await rejection;assert.equal(f.instances[0].disposed,true);assert.equal(host.inspect().artifacts.length,0);assert.equal(events.some(e=>e.kind==='progress'&&e.value.progress.phase==='late'),false);await host.dispose();});
test('cancel pins target and waits original owner terminal before next dispatch',async()=>{const entered=deferred(),finish=deferred(),stop=deferred(),f=setup({execute:async({request})=>{if(f.calls.length===1){entered.resolve();await finish.promise;}return {status:'EXECUTION_COMPLETED',tensor:tensor(),terminal:{originalTerminal:true,resourceReleased:true,reusable:true,resultAccepted:true}};},cancel:async()=>{stop.resolve();await finish.promise;return {stopped:true,originalTerminal:true,resourceReleased:true,reusable:true};}}),host=create(f.services);await host.configureModule('text',{});const first=host.execute({moduleId:'text',operation:'encode',input:{},outputRef:'first'});const rejected=assert.rejects(first,{code:'INVOCATION_CANCELLED'});await entered.promise;const target=host.inspect().activeTarget;await assert.rejects(host.cancel({...target,requestId:'wrong'}),{code:'TARGET_MISMATCH'});const cancel=host.cancel(target);await stop.promise;const second=host.execute({moduleId:'text',operation:'encode',input:{},outputRef:'second'});await Promise.resolve();assert.equal(f.calls.length,1);finish.resolve();const terminal=await cancel;await rejected;await second;assert.equal(terminal.originalTerminal,true);assert.equal(terminal.resourceReleased,true);await assert.rejects(host.cancel(target),{code:'STALE_INVOCATION'});await host.dispose();});
test('workspace preserves arbitrary metadata/packet bytes and restores zero model authority',async()=>{const f=setup(),host=create(f.services);await host.configureModule('text',{files:new Map([['model',new Blob(['model'])]]),manifest:{id:'native'}});await host.execute({moduleId:'text',operation:'encode',input:{},outputRef:'persist'});const bundle=await host.saveWorkspace();assert.ok(bundle.bytes instanceof Uint8Array);const next=create(f.services);const restored=await next.restoreWorkspace(new Blob([bundle.bytes]));assert.equal(restored.modelReselectionRequired,true);assert.equal(next.inspect().modules.text.configured,false);assert.equal(restored.fileRequirements.length,1);await next.configureModule('vae',{});await next.execute({moduleId:'vae',operation:'decode',input:{tensor:{$ref:'persist',path:'tensor'}},outputRef:'rerun'});assert.deepEqual(f.calls.at(-1).request.input.tensor.arbitrary,tensor().arbitrary);assert.deepEqual((await next.executeRoute({steps:[{stepId:'copy',moduleId:'vae',operation:'decode',input:{tensor:{$ref:'persist',path:'result.tensor'}},outputRef:'again'}],externalRefs:['persist']})).artifacts.persist.response.result.nativeExtra.mask,new Uint8Array([1,0]));await host.dispose();await next.dispose();});
test('implementation completion does not grant an unloaded LoRA binding or numerical acceptance',async()=>{const host=create(setup().services);const q=await host.query({moduleId:'lora',operation:'apply',input:{}});assert.equal(q.status,'UNSUPPORTED');assert.equal(host.inspect().fullImplementationComplete,true);assert.equal(host.inspect().generationReady,false);assert.equal(host.inspect().implementationReview.status,'PASSED');assert.deepEqual(host.inspect().implementationReview.missingCodePaths,[]);assert.equal(host.inspect().managedNumericalAcceptance,'AWAITING_HOLDER_RECEIPT');assert.equal(host.inspect().wholeOperationalExperiment,'NOT_RUN');assert.match(q.reasons[0].reason,/binding/i);await host.dispose();});
