test('unconfirmed cancellation quarantines until real disposal and fresh module creation recover',async()=>{const start=deferred(),end=deferred(),f=setup({execute:async()=>{start.resolve();await end.promise;return {status:'EXECUTION_COMPLETED',tensor:tensor()};},cancel:async()=>{end.resolve();return {stopped:false};}}),host=create(f.services);await host.configureModule('text',{});const run=host.execute({moduleId:'text',operation:'encode',input:{}}),reject=assert.rejects(run,{code:'INVOCATION_CANCELLED'});await start.promise;const terminal=await host.cancel(host.inspect().activeTarget);await reject;assert.equal(terminal.quarantined,true);await assert.rejects(host.execute({moduleId:'text',operation:'encode',input:{}}),{code:'RESOURCE_QUARANTINED'});await host.recover('text');assert.equal(f.instances[0].disposed,true);assert.equal(host.inspect().queue.groups[0].quarantined,false);await host.dispose();});
test('default real mean factory reports owner shape refusal without synthetic NN or normalization',async()=>{const host=mod.createOperationalManagement();try{await host.configureModule('mean',{});assert.equal(host.inspect().controlTestDouble,false);assert.equal(host.inspect().modules.mean.observation.sourceRef.commit,'b6e166478a8e072c9ffd3ce562bfdb0c89634920');const input={tensor:{dtype:'float32',layout:'NCTHW',shape:[1,16,21,60,104],meaning:'raw-posterior-mean',data:new Float32Array(1)}};const query=await host.query({moduleId:'mean',operation:'normalizeRawMean',input});assert.ok(query.reasons.some(r=>r.code==='OWNER_SHAPE_UNSUPPORTED'));await assert.rejects(host.execute({moduleId:'mean',operation:'normalizeRawMean',input}),e=>e.code==='OWNER_UNSUPPORTED'&&e.response.status==='UNSUPPORTED');}finally{await host.dispose();}});
