test('cancel while child preflight has no native target forwards signal and waits child cleanup',async()=>{const started=deferred(),finish=deferred(),observed=deferred();let released=false,nativeDispatch=0;const f=setup({execute:async({request})=>{started.resolve();request.signal.addEventListener('abort',()=>observed.resolve(),{once:true});await finish.promise;if(!request.signal.aborted)nativeDispatch++;released=true;throw Object.assign(Error('cancelled'),{code:'INVOCATION_CANCELLED'});}}),host=create(f.services);await host.configureModule('text',{});f.instances[0].inspect=()=>({activeTarget:null,queue:{groups:[{quarantined:false}],invocations:released?[{requestId:f.calls[0].request.requestId,originalTerminal:true,resourceReleased:true,calculationStopped:true,reusable:true}]:[]}});const first=host.execute({moduleId:'text',operation:'encode',input:{}}),rejected=assert.rejects(first,{code:'INVOCATION_CANCELLED'});await started.promise;let settled=false;const cancellation=host.cancel(host.inspect().activeTarget).then(value=>{settled=true;return value;});await observed.promise;await Promise.resolve();assert.equal(settled,false);finish.resolve();const terminal=await cancellation;await rejected;assert.equal(nativeDispatch,0);assert.equal(terminal.quarantined,false);assert.equal(terminal.stopConfirmed,true);await host.dispose();});
