test('failed previous owner disposal stays retained for recover before a replacement can open',async()=>{
 const f=setup(),host=create(f.services);
 await host.configureModule('text',{name:'old'});
 const old=f.instances[0];let disposalCalls=0;
 old.dispose=async()=>{disposalCalls++;if(disposalCalls===1)throw Object.assign(Error('first release failed'),{code:'RESOURCE_CLEANUP_FAILED'});old.disposed=true;};
 await assert.rejects(host.configureModule('text',{name:'replacement'}),{code:'RESOURCE_CLEANUP_FAILED'});
 assert.equal(f.instances.length,1,'a failed release must block replacement creation');
 assert.equal(host.inspect().modules.text.configured,false);
 assert.equal(host.inspect().modules.text.state,'recovery-required');
 await host.recover('text');
 assert.equal(old.disposed,true,'recover must retry the retained old owner');
 assert.equal(disposalCalls,2);
 assert.equal(f.instances.length,2);
 await host.dispose();
 assert.equal(old.disposed,true);
});
