test('superseded factory retirement must finish before a queued configuration or manager disposal can complete',async()=>{
 const firstEntered=deferred(),finishFactory=deferred(),retryEntered=deferred(),finishRelease=deferred();let creations=0,releases=0,open=false;
 const adapter={inspect:()=>({}),dispose:async()=>{releases++;if(releases===1)throw Object.assign(Error('release failed once'),{code:'RESOURCE_CLEANUP_FAILED'});retryEntered.resolve();await finishRelease.promise;open=false;}};
 const host=create({controlTestOnly:true,createModule:async()=>{creations++;open=true;firstEntered.resolve();await finishFactory.promise;return adapter;}});
 const first=host.configureModule('text',{version:1}),firstRejected=assert.rejects(first,{code:'RESOURCE_CLEANUP_FAILED'});await firstEntered.promise;
 const next=host.configureModule('text',{version:2});finishFactory.resolve();await firstRejected;await retryEntered.promise;
 assert.equal(creations,1);assert.equal(open,true);
 let disposed=false;const ending=host.dispose().then(value=>{disposed=true;return value;});await Promise.resolve();assert.equal(disposed,false);
 finishRelease.resolve();await next;await ending;assert.equal(creations,1);assert.equal(releases,2);assert.equal(open,false);assert.equal(host.inspect().disposed,true);
});

